mapper.select:
SELECT /* LGVATT20020.retrieveApprovalEnableTimeCheck */

        CASE WHEN rs.approval_enable_count > 0 AND rs.approval_disable_count = 0 THEN 'Y' ELSE 'N' END AS approval_enable_flag /* 결재 가능여부 */

FROM   (
        SELECT

               SUM(CASE WHEN SYSDATE < lgvatt_common_pkg.get_att_close_time(aur.subsidiary_code, 'UPD_APR', aur.time_and_attendance_date) THEN 1 ELSE 0 END) AS approval_enable_count /* 수정요청 근태일자 중 결재가능 건수 */
             , SUM(CASE WHEN SYSDATE < lgvatt_common_pkg.get_att_close_time(aur.subsidiary_code, 'UPD_APR', aur.time_and_attendance_date) THEN 0 ELSE 1 END) AS approval_disable_count /* 수정요청 근태일자 중 결재불가능 건수 */

        FROM   tb_att_update_req_n aur
        WHERE  aur.approval_request_id = #{requestMasterId}
        AND    aur.request_code        = #{requestCode}
       ) rs
